actions.script:
items = []
label = 'Requests'
if (!partyId) partyId = userId ? ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()?.partyId
        : ec.user.userAccount?.partyId
if (!partyId) return
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
if (!fromDate || !thruDate) {
    const today = ec.user.getPeriodRange('day', '0', String(toMillis(ec.user.nowTimestamp)))
    if (!fromDate) fromDate = today[0]
    if (!thruDate) thruDate = today[1]
}
const fromMillis = toMillis(fromDate)
const cf = ec.entity.conditionFactory
const found = ec.entity.find('mantle.request.RequestAndParty').condition('partyId', partyId).condition('roleTypeId', 'Assignee')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp))
        .condition(cf.makeCondition('statusId', 'not-in', ['ReqCompleted', 'ReqCancelled'], true))
        .condition(cf.makeCondition('responseRequiredDate', 'less', new Date(toMillis(thruDate))))
        .selectField('requestId').selectField('requestName').selectField('responseRequiredDate').selectField('priority')
        .selectField('statusId').orderBy('responseRequiredDate').list()
const seen = new Set()
for (const request of found) {
    if (seen.has(request.requestId)) continue
    seen.add(request.requestId)
    const due = toMillis(request.responseRequiredDate)
    items.push({kind: 'request', requestId: request.requestId, workEffortId: null, title: request.requestName || request.requestId,
        dueDate: new Date(due), overdue: due < fromMillis, startDate: null, endDate: null, allDay: false,
        priority: request.priority ?? null, statusId: request.statusId ?? null, assignees: [],
        record: {recordEntityName: 'mantle.request.Request', recordId: request.requestId,
            recordName: request.requestName ? `Request ${request.requestId} · ${request.requestName}` : `Request ${request.requestId}`},
        canUpdate: false, hasCallLink: false, source: null})
}

service-call.in-map:
{communicationEventTypeId:'Comment', contactMechTypeEnumId:'CmtWebForm', statusId:'CeSent',
                        fromPartyId:ec.user.userAccount.partyId, entryDate:ec.user.nowTimestamp,
                        contentType:contentType, subject:subject, body:body}

actions.script:
const joined = ec.entity.find('mantle.request.RequestCommEvent').condition('requestId', requestId)
        .condition('communicationEventId', communicationEventId).count() > 0
const value = joined ? ec.entity.find('mantle.party.communication.CommunicationEvent')
        .condition('communicationEventId', communicationEventId).one() : null
if (value == null || value.statusId === 'CeCancelled') {
    ec.message.addError(`Comment ${communicationEventId} not found on request ${requestId}`); return }
if (value.communicationEventTypeId !== 'Comment') {
    ec.message.addError(`Communication event ${communicationEventId} is not a comment: a message once sent stays as it is`); return }
const partyId = ec.user.userAccount?.partyId || null
const isAuthor = !!partyId && value.fromPartyId === partyId
if (action === 'delete') {
    if (!isAuthor && !(ec.user.userId && ec.user.isInGroup('ADMIN'))) { ec.message.addError('You may delete only your own comments'); return }
} else if (!isAuthor) { ec.message.addError('You may change only your own comments'); return }
commEvent = value.getMap()

created = false
const request = ec.entity.find('mantle.request.Request').condition('requestId', requestId).one()
if (request == null) { ec.message.addError(`Request ${requestId} not found`); return }
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
recordEntityName = info.recordEntityName

let keys
if (info.requestJoin) {
    linkEntityName = info.requestJoin.entityName
    keys = {requestId: requestId, [info.requestJoin.keyField]: recordId}
} else {
    linkEntityName = 'mantle.request.RequestRecord'
    keys = {requestId: requestId, recordEntityName: recordEntityName, recordId: recordId}
}
if (ec.entity.find(linkEntityName).condition(keys).one() != null) return
const fields = info.requestJoin ? keys : Object.assign({linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp}, keys)
ec.service.sync().name('create#' + linkEntityName).parameters(fields).call()
if (ec.message.hasError()) return
created = true

unlinked = false
const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo')
        .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError()) return
const removeRows = (entityName, keys) => {
    for (const row of ec.entity.find(entityName).condition(keys).list()) {
        ec.service.sync().name('delete#' + entityName).parameters(row.getPrimaryKeys()).call()
        if (ec.message.hasError()) return
        unlinked = true
    }
}
if (info.requestJoin) removeRows(info.requestJoin.entityName, {requestId: requestId, [info.requestJoin.keyField]: recordId})
removeRows('mantle.request.RequestRecord', {requestId: requestId, recordEntityName: info.recordEntityName, recordId: recordId})

const listOf = (text) => String(text || '').split(',').map((part) => part.trim()).filter((part) => part)
let own = {}
if (workEffortId) {
    const out = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId,
        organizationPartyId: organizationPartyId || null}).disableAuthz().call() || {}
    own = out.settings || {}
    organizationPartyId = out.organizationPartyId || organizationPartyId || null
}
const appSetting = (typeId) => {
    if (!organizationPartyId) return {}
    const row = ec.entity.find('mantle.party.PartySetting').condition('partyId', organizationPartyId).condition('partySettingTypeId', typeId).disableAuthz().one()
    if (!row?.settingValue) return {}
    try { const parsed = JSON.parse(row.settingValue); return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {} }
    catch (err) { ec.logger.error(`Intake settings of ${organizationPartyId}: ${typeId} is not JSON, skipped: ${err}`); return {} }
}
const intake = appSetting('ProjIntake')
const form = appSetting('ProjPublicForm')
const types = Array.from(ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'RequestType').useCache(true).disableAuthz().list())
        .map((row) => row.enumId)
const known = (list) => list.filter((id) => types.includes(id))
let offered = known(listOf(own.WstRequestTypes || intake.offered))
if (!offered.length) offered = known(['RqtBugFix', 'RqtNewFeature', 'RqtSupport', 'RqtInformation', 'RqtProposal'])
let triaged = known(listOf(intake.triaged))
if (!triaged.length && intake.triaged == null) triaged = known(['RqtBugFix', 'RqtNewFeature', 'RqtProposal'])
let defaultType = own.WstRequestType || intake.defaultType || null
if (!defaultType || !types.includes(defaultType)) defaultType = offered.includes('RqtSupport') ? 'RqtSupport' : (offered[0] || 'RqtSupport')
const yn = (value, fallback) => value == null || value === '' ? fallback : ((value === true || value === 'Y' || value === 'true') ? 'Y' : 'N')
const count = (value, fallback, max) => { const number = Math.floor(Number(value)); return Number.isFinite(number) && number > 0 ? Math.min(number, max) : fallback }
settings = {accountId: own.WstIntakeAccount || null, plusTag: own.WstIntakePlusTag || null, token: own.WstIntakeToken || null,
    triagePartyId: own.WstTriageParty || intake.triagePartyId || null, defaultType: defaultType, offeredTypes: offered, triagedTypes: triaged,
    requestFromWork: own.WstRequestFromWork === 'Y' || (own.WstRequestFromWork == null && listOf(own.WstModules).includes('requests')) ? 'Y' : 'N',
    publicForm: {captcha: yn(form.captcha, 'N'), files: yn(form.files, 'Y'), maxMb: count(form.maxMb, 10, 50), maxFiles: count(form.maxFiles, 5, 10),
        confirm: yn(form.confirm, 'Y')}}

const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (project == null || project.workEffortTypeEnumId !== 'WetProject') { ec.message.addError(`Project ${workEffortId} not found`); return }
token = ec.user.randomString(32).replace(/[^A-Za-z0-9_-]/g, 'x')
ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: workEffortId,
    settingTypeEnumId: 'WstIntakeToken', settingValue: token}).call()

project = null
const text = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(text)) return
const setting = Array.from(ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('settingTypeEnumId', 'WstIntakeToken')
        .condition('settingValue', text).disableAuthz().list())[0]
if (setting == null) return
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', setting.workEffortId).disableAuthz().one()
if (row == null || row.workEffortTypeEnumId !== 'WetProject' || row.isTemplate === 'Y') return
if (['WeComplete', 'WeClosed', 'WeCancelled'].includes(row.statusId)) return
project = row.getMap()

valid = false
routeContext = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const project = ec.service.sync().name('mantle.request.RequestServices.find#IntakeProject').parameters({token: token}).call()?.project
    if (project == null) return
    const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: project.workEffortId})
            .call()?.settings || {}
    const label = (id) => ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id
    const form = settings.publicForm || {}
    const siteKey = form.captcha === 'Y' ? (ec.user.getPreference('reCAPTCHA.site.key') || null) : null
    valid = true
    routeContext = {projectName: project.workEffortName || '', typeList: Array.from(settings.offeredTypes || []).map((id) => ({enumId: id, label: label(id)})),
        defaultType: settings.defaultType || null, filesAllowed: form.files === 'Y', maxFiles: form.maxFiles || 5, maxMb: form.maxMb || 10,
        captchaSiteKey: siteKey}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

requestId = null
received = false
const L = (text) => ec.l10n.localize(text)
const fail = (text) => { ec.message.addError(L(text)) }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const project = ec.service.sync().name('mantle.request.RequestServices.find#IntakeProject').parameters({token: token}).call()?.project
    if (project == null) { fail('This form is not available'); return }
    if (website != null && String(website).trim() !== '') {
        ec.logger.warn(`Public request form of ${project.workEffortId}: the honeypot was filled, nothing made`)
        received = true
        return
    }
    const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: project.workEffortId})
            .call()?.settings || {}
    const form = settings.publicForm || {}
    const clean = (value, max) => String(value == null ? '' : value).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim().substring(0, max)
    const first = clean(firstName, 60), last = clean(lastName, 60), email = clean(emailAddress, 254).toLowerCase()
    const subject = clean(requestName, 255).replace(/\s+/g, ' '), text = clean(description, 20000), org = clean(organizationName, 100)
    if (!first || !last) { fail('Your first and last name, please'); return }
    if (!/^[^\s@<>()",;:]+@[^\s@<>()",;:]+\.[^\s@<>()",;:]+$/.test(email)) { fail('An email address we can answer, please'); return }
    if (!subject) { fail('A subject, please'); return }
    if (!text) { fail('Tell us what you need in the description, please'); return }
    let typeId = requestTypeEnumId ? String(requestTypeEnumId) : (settings.defaultType || null)
    if (!Array.from(settings.offeredTypes || []).includes(typeId)) {
        if (requestTypeEnumId) { fail('Choose one of the request types offered'); return }
        typeId = Array.from(settings.offeredTypes || [])[0] || 'RqtSupport'
    }
    // the files: how many, how big, which kinds, their names cleaned
    const files = Array.from(fileList || []).filter((file) => file != null && Number(file.size || 0) > 0)
    if (files.length && form.files !== 'Y') { fail('This form takes no files'); return }
    if (files.length > (form.maxFiles || 5)) { fail(ec.resource.expand('At most ${count} files, please', '', {count: form.maxFiles || 5})); return }
    const allowed = /\.(png|jpe?g|gif|webp|bmp|pdf|txt|log|csv|md|json|xml|docx?|xlsx?|pptx?|odt|ods|odp|rtf|zip|gz|eml)$/i
    const maxBytes = (form.maxMb || 10) * 1048576
    const fileNames = []
    for (const file of files) {
        const name = String(file.getName ? file.getName() : (file.name || 'file')).split(/[\\/]/).pop()
                .replace(/[^A-Za-z0-9._ -]/g, '_').replace(/^\.+/, '').substring(0, 120) || 'file'
        if (!allowed.test(name)) { fail(ec.resource.expand('${name}: this kind of file is not taken', '', {name})); return }
        if (Number(file.size || 0) > maxBytes) { fail(ec.resource.expand('${name} is larger than ${max} MB', '', {name, max: form.maxMb || 10})); return }
        fileNames.push(name)
    }
    // how often: the project's form, and the address
    const nowValue = ec.user.nowTimestamp
    const nowMillis = typeof nowValue === 'number' ? nowValue : (nowValue instanceof Date ? nowValue.getTime() : Number(String(nowValue)))
    const hourAgo = new Date(nowMillis - 3600000)
    const recent = ec.entity.find('mantle.request.Request').condition('rootWorkEffortId', project.workEffortId).condition('salesChannelEnumId', 'ScWeb')
            .condition('requestDate', 'greater-equals', hourAgo).count()
    if (recent >= 30) {
        ec.logger.warn(`Public request form of ${project.workEffortId}: ${recent} requests in the last hour, refused for now`)
        fail('This form takes no more requests just now; try again in an hour'); return
    }
    const addressIds = Array.from(ec.entity.find('mantle.party.contact.ContactMech').condition('infoString', email).selectField('contactMechId').list())
            .map((row) => row.contactMechId)
    if (addressIds.length && ec.entity.find('mantle.request.Request').condition('emailContactMechId', 'in', addressIds)
            .condition('salesChannelEnumId', 'ScWeb').condition('requestDate', 'greater-equals', hourAgo).count() >= 5) {
        fail('You sent several requests just now; try again in an hour'); return
    }
    const contact = {statusId: 'ReqSubmitted', priority: 5, requestTypeEnumId: typeId, requestName: subject, description: text,
        firstName: first, lastName: last, emailAddress: email, filedByPartyId: null, customerPartyId: null}
    const created = form.captcha === 'Y'
        ? ec.service.sync().name('mantle.request.RequestServices.create#ContactRequestReCaptcha').parameters(Object.assign({reCaptchaToken: reCaptchaToken || null}, contact)).call()
        : ec.service.sync().name('mantle.request.RequestServices.create#ContactRequest').parameters(contact).call()
    if (ec.message.hasError() || !created?.requestId) {
        const said = ec.message.getErrorsString()
        ec.logger.warn(`Public request form of ${project.workEffortId}: not made: ${said}`)
        ec.message.clearErrors()
        fail(form.captcha === 'Y' && /captcha/i.test(said) ? 'Confirm you are not a robot, then send it again' : 'Your request could not be sent; check the fields and try again')
        return
    }
    requestId = created.requestId
    received = true
    ec.service.sync().name('update#mantle.request.Request').parameters({requestId: requestId, rootWorkEffortId: project.workEffortId,
        salesChannelEnumId: 'ScWeb'}).call()
    if (org) ec.service.sync().name('create#mantle.request.RequestNote').parameters({requestId: requestId, noteDate: ec.user.nowTimestamp,
        noteText: ec.resource.expand('Organization (as the requester gave it): ${org}', '', {org})}).call()
    if (settings.triagePartyId) ec.service.sync().name('create#mantle.request.RequestParty').parameters({requestId: requestId,
        partyId: settings.triagePartyId, roleTypeId: 'Assignee', fromDate: ec.user.nowTimestamp}).call()
    // each file on its own: one that cannot be kept is logged and the request stands
    files.forEach((file, index) => {
        try {
            const content = ec.service.sync().name('create#mantle.request.RequestContent').parameters({requestId: requestId,
                contentTypeEnumId: 'RqCntUserDefined', description: fileNames[index], contentDate: ec.user.nowTimestamp}).call()
            const location = `dbresource://mantle/content/request/${requestId}/content_${content.requestContentId}/${fileNames[index]}`
            const stream = file.getInputStream()
            try { ec.resource.getLocationReference(location).putStream(stream) } finally { stream.close() }
            ec.service.sync().name('update#mantle.request.RequestContent').parameters({requestContentId: content.requestContentId,
                contentLocation: location}).call()
        } catch (err) {
            ec.logger.error(`Public request form: file ${fileNames[index]} of request ${requestId} not kept: ${err && err.message ? err.message : err}`)
        }
    })
    if (form.confirm === 'Y' && settings.accountId) ec.service.sync().name('mantle.request.RequestServices.send#IntakeConfirmation')
            .parameters({requestId: requestId, emailAccountId: settings.accountId}).call()
    ec.message.clearErrors()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

requestId = null
created = false
joined = false
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const message = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
    if (message == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    const already = Array.from(ec.entity.find('mantle.request.RequestEmailMessage').condition('emailMessageId', emailMessageId).list())[0]
    if (already) { requestId = already.requestId; return }
    const thread = ec.service.sync().name('mantle.request.RequestServices.find#EmailRequest').parameters({emailMessageId: emailMessageId}).call()
    if (thread?.requestId) {
        requestId = thread.requestId
        joined = true
        ec.service.sync().name('mantle.request.RequestServices.file#RequestEmail').parameters({requestId: requestId, emailMessageId: emailMessageId}).call()
        return
    }
    const project = ec.service.sync().name('mantle.request.RequestServices.find#EmailIntakeProject').parameters({emailMessageId: emailMessageId,
        emailAccountId: emailAccountId || message.emailAccountId, ruleOwnerUserId: ruleOwnerUserId || null, value: value || null}).call()?.project || null
    const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: project?.workEffortId || null,
        organizationPartyId: project ? null : (ec.service.sync().name('mantle.request.RequestServices.get#EmailAccountOrganization')
            .parameters({emailAccountId: emailAccountId || message.emailAccountId}).call()?.organizationPartyId || null)}).call()?.settings || {}
    const sender = ec.service.sync().name('mantle.request.RequestServices.findOrCreate#EmailSender').parameters({emailMessageId: emailMessageId}).call() || {}
    const text = String(message.bodyText || String(message.body || '').replace(/<(style|script)[^>]*>[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>/gi, '\n')
            .replace(/<\/p>/gi, '\n\n').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')).trim()
    const out = ec.service.sync().name('mantle.request.RequestServices.create#Request').parameters({requestName: String(message.subject || '').trim().substring(0, 255)
            || ec.l10n.localize('(no subject)'), description: text.substring(0, 20000), statusId: 'ReqSubmitted', requestTypeEnumId: settings.defaultType || 'RqtSupport',
        rootWorkEffortId: project?.workEffortId || null, salesChannelEnumId: 'ScEmail', requestDate: message.receivedDate || message.messageDate || ec.user.nowTimestamp,
        filedByPartyId: sender.partyId || null, customerPartyId: sender.partyId || null, emailContactMechId: sender.contactMechId || null,
        assignToPartyId: settings.triagePartyId || null}).call()
    if (ec.message.hasError()) return
    requestId = out.requestId
    created = true
    ec.service.sync().name('mantle.request.RequestServices.file#RequestEmail').parameters({requestId: requestId, emailMessageId: emailMessageId}).call()
    if (ec.message.hasError()) return
    if (settings.publicForm?.confirm === 'Y' && settings.accountId && settings.accountId === (emailAccountId || message.emailAccountId))
        ec.service.sync().name('mantle.request.RequestServices.send#IntakeConfirmation').parameters({requestId: requestId,
            emailAccountId: settings.accountId, parentEmailMessageId: emailMessageId}).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

workEffortId = null
requestId = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const message = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).one()
    if (message == null) { ec.message.addError(`Email message ${emailMessageId} not found`); return }
    const asRequest = () => {
        const out = ec.service.sync().name('mantle.request.RequestServices.create#RequestFromEmail').parameters({emailMessageId, emailAccountId,
            emailRuleId, ruleOwnerUserId, value}).call()
        requestId = out?.requestId || null
    }
    if (ec.entity.find('mantle.request.RequestEmailMessage').condition('emailMessageId', emailMessageId).count() > 0) return asRequest()
    const event = Array.from(ec.entity.find('mantle.party.communication.CommunicationEvent').condition('emailMessageId', emailMessageId).list())[0]
    if (event && ec.entity.find('mantle.work.effort.WorkEffortCommEvent').condition('communicationEventId', event.communicationEventId).count() > 0) return
    const project = ec.service.sync().name('mantle.request.RequestServices.find#EmailIntakeProject').parameters({emailMessageId: emailMessageId,
        emailAccountId: emailAccountId || message.emailAccountId, ruleOwnerUserId: ruleOwnerUserId || null, value: value || null}).call()?.project || null
    if (project == null) return asRequest()
    // an internal sender: a user with the address whose party holds a current role on the project
    const address = String(message.fromAddress || '').trim().toLowerCase()
    const account = address ? Array.from(ec.entity.find('moqui.security.UserAccount').condition('emailAddress', address).list())
            .concat(Array.from(ec.entity.find('moqui.security.UserAccount').condition('username', address).list()))
            .find((user) => user.partyId && user.disabled !== 'Y') : null
    const member = account && ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', project.workEffortId)
            .condition('partyId', account.partyId).conditionDate('fromDate', 'thruDate', null).count() > 0
    if (!member) return asRequest()
    const text = String(message.bodyText || String(message.body || '').replace(/<[^>]*>/g, ' ')).trim()
    const out = ec.service.sync().name('mantle.work.TaskServices.create#Task').parameters({rootWorkEffortId: project.workEffortId,
        workEffortName: String(message.subject || '').trim().substring(0, 255) || ec.l10n.localize('(no subject)'), description: text.substring(0, 20000),
        purposeEnumId: 'WepTask', ownerPartyId: account.partyId, statusFlowId: project.statusFlowId || null}).call()
    if (ec.message.hasError()) return
    workEffortId = out.workEffortId
    ec.service.sync().name('create#mantle.work.effort.WorkEffortParty').parameters({workEffortId: workEffortId, partyId: account.partyId,
        roleTypeId: 'Reporter', fromDate: ec.user.nowTimestamp}).call()
    const comm = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent').parameters({emailMessageId: emailMessageId,
        contactOwnerUserIdList: []}).call()
    if (comm?.communicationEventId) ec.service.sync().name('create#mantle.work.effort.WorkEffortCommEvent').parameters({workEffortId: workEffortId,
        communicationEventId: comm.communicationEventId}).call()
    for (const file of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list()) {
        if (!file.attachmentLocation || file.isInline === 'Y') continue
        try {
            const name = String(file.fileName || 'attachment').replace(/[\/\\?#%:]/g, '_')
            const content = ec.service.sync().name('create#mantle.work.effort.WorkEffortContent').parameters({workEffortId: workEffortId,
                contentTypeEnumId: 'WectUserDefined', description: name, contentDate: ec.user.nowTimestamp}).call()
            const location = `dbresource://mantle/content/workEffort/${workEffortId}/content_${content.workEffortContentId}/${name}`
            ec.resource.getLocationReference(location).copyFrom(file.attachmentLocation)
            ec.service.sync().name('update#mantle.work.effort.WorkEffortContent').parameters({workEffortContentId: content.workEffortContentId,
                contentLocation: location}).call()
        } catch (err) {
            ec.logger.error(`Work item ${workEffortId} from email ${emailMessageId}: file ${file.fileName} not kept: ${err && err.message ? err.message : err}`)
        }
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

project = null
const message = ec.entity.find('moqui.basic.email.EmailMessage').condition('emailMessageId', emailMessageId).disableAuthz().one()
if (message == null) return
const setting = (workEffortId, typeId) => ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', workEffortId)
        .condition('settingTypeEnumId', typeId).disableAuthz().one()?.settingValue || null
let candidates = []
if (value) {
    candidates = [String(value).trim()]
} else {
    const tags = new Set()
    for (const list of [message.toAddresses, message.ccAddresses]) for (const match of String(list || '').matchAll(/[^\s<>,;"]+\+([A-Za-z0-9._-]+)@[^\s<>,;"]+/g))
        tags.add(match[1].toLowerCase())
    if (!tags.size) return
    candidates = Array.from(ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('settingTypeEnumId', 'WstIntakePlusTag').disableAuthz().list())
            .filter((row) => tags.has(String(row.settingValue || '').trim().toLowerCase())).map((row) => row.workEffortId)
    candidates.sort((left, right) => (setting(right, 'WstIntakeAccount') === emailAccountId ? 1 : 0) - (setting(left, 'WstIntakeAccount') === emailAccountId ? 1 : 0))
}
const ownerPartyId = ruleOwnerUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', ruleOwnerUserId).disableAuthz().one()?.partyId : null
for (const id of candidates) {
    const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).disableAuthz().one()
    if (row == null || row.workEffortTypeEnumId !== 'WetProject') { ec.logger.warn(`Email ${emailMessageId}: ${id} is not a project, the request has none`); continue }
    const byAccount = emailAccountId && setting(id, 'WstIntakeAccount') === emailAccountId
    const byOwner = ownerPartyId && ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', id).condition('partyId', ownerPartyId)
            .conditionDate('fromDate', 'thruDate', null).disableAuthz().count() > 0
    if (!byAccount && !byOwner) {
        ec.logger.warn(`Email ${emailMessageId}: the rule of ${ruleOwnerUserId || 'nobody'} on account ${emailAccountId} may not file into project ${id}`)
        continue
    }
    project = row.getMap()
    return
}

organizationPartyId = null
if (!emailAccountId) return
const account = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', emailAccountId).disableAuthz().one()
const partyId = account?.ownerUserId ? ec.entity.find('moqui.security.UserAccount').condition('userId', account.ownerUserId).disableAuthz().one()?.partyId : null
if (!partyId) return
const internal = new Set(Array.from(ec.entity.find('mantle.party.PartyRole').condition('roleTypeId', 'OrgInternal').disableAuthz().list()).map((row) => row.partyId))
const rel = Array.from(ec.entity.find('mantle.party.PartyRelationship').condition('fromPartyId', partyId).conditionDate('fromDate', 'thruDate', null)
        .disableAuthz().list()).find((row) => internal.has(row.toPartyId))
organizationPartyId = rel?.toPartyId || null

requestId = null
