const referenced = String(message.inReplyTo || '').split(/\s+/).concat(String(message.referencesHeader || '').split(/\s+/))
        .map((id) => id.trim()).filter((id) => /^<[^<>\s]+>$/.test(id))
if (referenced.length) for (const row of ec.entity.find('moqui.basic.email.EmailMessage').condition('messageId', 'in', Array.from(new Set(referenced)).slice(0, 50))
