    if (!address.includes('@')) return
    const user = Array.from(ec.entity.find('moqui.security.UserAccount').condition('emailAddress', address).list()).find((row) => row.partyId)
    const infos = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('infoString', address)
            .conditionDate('fromDate', 'thruDate', null).list())
    for (const info of infos) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', info.partyId).one()
        if (party == null || party.disabled === 'Y' || party.privateOwnerUserId) continue
        if (user?.partyId && info.partyId !== user.partyId && infos.some((other) => other.partyId === user.partyId)) continue
        partyId = info.partyId
        contactMechId = info.contactMechId
        break
    }
    if (!partyId && user?.partyId) partyId = user.partyId
    if (partyId) return
    const name = String(message.fromName || '').replace(/["']/g, '').trim() || address.split('@')[0]
    const parts = name.split(/\s+/)
    // a person needs both names: one word (or none) takes the address's domain as its last name
    const firstName = parts.length > 1 ? parts.slice(0, -1).join(' ') : parts[0]
    const lastName = parts.length > 1 ? parts[parts.length - 1] : '@' + address.split('@')[1]
    const person = ec.service.sync().name('mantle.party.PartyServices.create#Person').parameters({firstName: firstName.substring(0, 60),
        lastName: lastName.substring(0, 60), roleTypeId: 'Customer'}).call()
    partyId = person?.partyId || null
    if (!partyId) return
    const email = ec.service.sync().name('mantle.party.ContactServices.create#EmailAddress').parameters({partyId: partyId, emailAddress: address,
        contactMechPurposeId: 'EmailPrimary'}).call()
    contactMechId = email?.contactMechId || null
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

