    const sender = ec.entity.find('mantle.request.RequestParty').condition('requestId', requestId).condition('roleTypeId', 'Reporter').one()
    step('link', () => {
        if (ec.entity.find('mantle.request.RequestEmailMessage').condition('requestId', requestId).condition('emailMessageId', emailMessageId).count() > 0) return
        ec.service.sync().name('create#mantle.request.RequestEmailMessage').parameters({requestId: requestId, emailMessageId: emailMessageId,
            partyId: sender?.partyId || null}).call()
    })
    step('conversation', () => {
        const out = ec.service.sync().name('mantle.party.CommunicationServices.create#EmailCommunicationEvent').parameters({emailMessageId: emailMessageId,
            contactOwnerUserIdList: []}).call()
        communicationEventId = out?.communicationEventId || null
        if (communicationEventId && ec.entity.find('mantle.request.RequestCommEvent').condition('requestId', requestId)
                .condition('communicationEventId', communicationEventId).count() === 0)
            ec.service.sync().name('create#mantle.request.RequestCommEvent').parameters({requestId: requestId, communicationEventId: communicationEventId}).call()
    })
    for (const file of ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition('emailMessageId', emailMessageId).list()) {
        if (!file.attachmentLocation || file.isInline === 'Y') continue
        step('file ' + (file.fileName || file.emailMessageAttachmentId), () => {
            const name = String(file.fileName || 'attachment').split(/[\\/]/).pop().replace(/[^A-Za-z0-9._ -]/g, '_').replace(/^\.+/, '').substring(0, 120) || 'attachment'
            const content = ec.service.sync().name('create#mantle.request.RequestContent').parameters({requestId: requestId,
                contentTypeEnumId: 'RqCntUserDefined', description: name, contentDate: message.receivedDate || ec.user.nowTimestamp}).call()
            const location = `dbresource://mantle/content/request/${requestId}/content_${content.requestContentId}/${name}`
            ec.resource.getLocationReference(location).copyFrom(file.attachmentLocation)
            ec.service.sync().name('update#mantle.request.RequestContent').parameters({requestContentId: content.requestContentId,
                contentLocation: location}).call()
        })
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

emailMessageId = null
