        const settings = ec.service.sync().name('mantle.request.RequestServices.get#IntakeSettings').parameters({workEffortId: request.rootWorkEffortId}).call()?.settings || {}
        if (settings.triagePartyId) partyIds.add(settings.triagePartyId)
