const purpose = purposeEnumId || ({RqtBugFix: 'WepFix', RqtNewFeature: 'WepNewFeature'}[request.requestTypeEnumId] || 'WepTask')
const out = ec.service.sync().name('mantle.work.TaskServices.create#Task').parameters({rootWorkEffortId: projectId,
    parentWorkEffortId: parentWorkEffortId || null, milestoneWorkEffortId: milestoneWorkEffortId || null,
    workEffortName: String(workEffortName || request.requestName || requestId).trim().substring(0, 255), purposeEnumId: purpose,
    priority: priority ?? request.priority ?? 5, estimatedCompletionDate: estimatedCompletionDate ?? request.responseRequiredDate ?? null,
