workEffortId = out.workEffortId
const fields = {requestId: requestId}
if (!request.rootWorkEffortId) fields.rootWorkEffortId = projectId
if (request.statusId === 'ReqSubmitted') fields.statusId = 'ReqReviewed'
if (Object.keys(fields).length > 1) ec.service.sync().name('mantle.request.RequestServices.update#Request').parameters(fields).call()

changedList = []
const STARTED = ['WeInProgress', 'WeInReview', 'WeInTesting']
const DONE = ['WeComplete', 'WeClosed']
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const item = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    if (item == null || item.workEffortTypeEnumId !== 'WetTask') return
    for (const link of ec.entity.find('mantle.request.RequestWorkEffort').condition('workEffortId', workEffortId).list()) {
