            if (request == null || ['ReqCompleted', 'ReqCancelled', 'ReqDraft'].includes(request.statusId)) continue
            // a project's requests and work only (a personal task on a Commons request moves nothing)
            const projectId = request.rootWorkEffortId || item.rootWorkEffortId
            if (!projectId || !item.rootWorkEffortId) continue
            // on when the project says Y, or says nothing and has the Requests module (Projects' default; a project
            // outside Projects, with no modules, keeps Mantle's own way: its requests are completed by hand)
            const projectSettings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: projectId}).call()?.settings || {}
            const follows = projectSettings.WstRequestFromWork === 'Y' || (projectSettings.WstRequestFromWork == null
                    && String(projectSettings.WstModules || '').split(',').map((key) => key.trim()).includes('requests'))
            if (!follows) continue
            const ids = Array.from(ec.entity.find('mantle.request.RequestWorkEffort').condition('requestId', request.requestId).list()).map((row) => row.workEffortId)
            const items = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids)
                    .condition('workEffortTypeEnumId', 'WetTask').list())
            const live = items.filter((row) => row.statusId !== 'WeCancelled')
