            else if (request.statusId !== 'ReqInProgress' && items.some((row) => STARTED.includes(row.statusId) || DONE.includes(row.statusId))) toStatusId = 'ReqInProgress'
            if (!toStatusId || toStatusId === request.statusId) continue
            const fields = {requestId: request.requestId, statusId: toStatusId}
            if (toStatusId === 'ReqCompleted') fields.requestResolutionEnumId = request.requestTypeEnumId === 'RqtBugFix' ? 'RrFixed' : 'RrCompleted'
            ec.service.sync().name('update#mantle.request.Request').parameters(fields).call()
